import SwiftUI

struct FoodSearchView: View {
    
    // What the user types into the search field
    @State private var searchText = ""
    
    // Foods returned from USDA
    @State private var foods: [USDAFood] = []
    
    // Tracks whether a search is currently running
    @State private var isLoading = false
    
    // Message shown if the USDA request fails
    @State private var errorMessage = ""
    
    // Connect this screen to the USDA networking service
    private let foodService = USDAFoodService()
    
    var body: some View {
        VStack(spacing: 12) {
            
            HStack {
                TextField("Search for a food", text: $searchText)
                    .textFieldStyle(.roundedBorder)
                    .submitLabel(.search)
                    .onSubmit {
                        Task {
                            await searchFoods()
                        }
                    }
                
                Button("Search") {
                    Task {
                        await searchFoods()
                    }
                }
                .disabled(
                    searchText.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty
                    || isLoading
                )
            }
            .padding(.horizontal)
            
            if isLoading {
                ProgressView("Searching USDA...")
            }
            
            if !errorMessage.isEmpty {
                Text(errorMessage)
                    .foregroundColor(.red)
                    .font(.footnote)
                    .padding(.horizontal)
            }
            
            List(foods) { food in
                
                NavigationLink {
                    
                    FoodDetailView(food: food)
                    
                } label: {
                    
                    VStack(alignment: .leading, spacing: 4) {
                        
                        Text(food.description)
                            .font(.headline)
                        
                        if let brandOwner = food.brandOwner,
                           !brandOwner.isEmpty {
                            
                            Text(brandOwner)
                                .font(.subheadline)
                                .foregroundColor(.secondary)
                        }
                        
                        if let dataType = food.dataType {
                            
                            Text(dataType)
                                .font(.caption)
                                .foregroundColor(.secondary)
                        }
                    }
                    .padding(.vertical, 4)
                }
            }
        }
        .navigationTitle("Food Search")
    }
    
    
    @MainActor
    private func searchFoods() async {
        
        errorMessage = ""
        isLoading = true
        
        do {
            
            foods = try await foodService.searchFoods(query: searchText)
            
            isLoading = false
            
        } catch is CancellationError {
            
            isLoading = false
            print("USDA food search was cancelled.")
            
        } catch {
            
            foods = []
            isLoading = false
            
            errorMessage = "Could not search foods. Please try again."
            
            print("USDA food search failed: \(error.localizedDescription)")
        }
    }
}


